def fm(x):
    sources='\n'.join(f'  - {s}' for s in x.sources)
    return f'''---
note_id: {x.note_id}
note_type: concept-deep-dive
status: review
language: vi
created: 2026-10-01
last_verified: 2026-10-01
editorial_pass: humanized-v1
primary_question: {x.question}
source_ids:
{sources}
aliases: [{x.title}]
tags: [wiki/database-systems, semantic-layer, metricflow, module-12]
reference_path: Material/DE/Reference/Library/Knowledge-Notes/PACK-DATABASE-MODELING-BOOK-01/{x.filename}
---
'''

def deep_note(x):
    parts=[fm(x),f'# {x.title}\n\n> [!abstract] Câu hỏi trung tâm\n> {x.question}\n']
    for i,(heading,body) in enumerate(x.core,1): parts.append(f'\n## {i}. {heading}\n\n{body}\n')
    parts.append('\n## 8. Ma trận kiểm chứng từng mệnh đề\n\nMọi mệnh đề dưới đây cần fixture, invariant, independent oracle và output lưu được. Compile thành công hoặc con số nhìn hợp lý không đủ làm bằng chứng.\n')
    for i,probe in enumerate(x.probes,1):
        parts.append(f'''\n### 8.{i}. {probe}\n\n**Mệnh đề cần kiểm.** {probe}.\n\n**Cách kiểm.** {VERIFY[x.number]} Với mệnh đề này, ghi data shape gây lỗi, expected result và failure signal. Không dùng generated query làm oracle cho chính nó.\n\n**Bằng chứng đạt.** Lưu contract/graph/config version, seed snapshot, command/SQL, raw output, row/multiplicity ledger và semantic diff. Nếu chưa chạy tool/lab, trạng thái chỉ là test protocol.\n''')
    parts.append('''\n## 9. Quy trình phản biện\n\n1. Viết population, grain, identities, time và aggregation trước tool syntax.\n2. Gắn metric/dimension với qualified entity role và allowed path.\n3. Đếm rows, distinct base keys, unmatched và match multiplicity sau từng join edge.\n4. Dùng independent oracle từ atomic facts; so intermediate components trước final value.\n5. Chạy invalid cases cùng valid siblings để bắt underblocking và overblocking.\n6. Khóa exact tool/config/mart versions; compile output và diagnostics là version-specific evidence.\n7. Lưu failed runs, limitations và trigger làm certification hết hiệu lực.\n\n## 10. Câu hỏi tự kiểm tra\n\n1. Join path nào được chọn và business role nào biện minh cho nó?\n2. Base fact keys có bị nhân hoặc mất sau từng edge không?\n3. Dimension có reachable, đúng grain và compatible với aggregation không?\n4. Parse/validate/compile/reconciliation xác nhận những lớp khác nhau nào?\n5. Generated SQL khác contract ở population, filter, path hay aggregation nào?\n6. Bằng chứng nào độc lập với engine output đang được kiểm?\n\n## 11. Giới hạn và điều chưa cho phép kết luận\n\n- Chưa chạy MetricFlow, warehouse queries, execution plans hoặc labs; note mô tả protocol và expected evidence.\n- dbt/MetricFlow docs được kiểm ngày 2026-10-01; commands và YAML phụ thuộc engine/version/environment.\n- Thuật ngữ fan/chasm có thể khác giữa sản phẩm; invariant của bài là grain, multiplicity, population và semantic path.\n- Kimball–Ross và PostgreSQL hỗ trợ modeling/SQL mechanics; compatibility/certification workflow là curriculum synthesis.\n- Owner chưa phê duyệt semantic meaning nên note giữ trạng thái `review`.\n''')
    refs='\n'.join(f'{i}. [[{s}]]' for i,s in enumerate(x.source_links,1))
    coverage='\n'.join(f'| [[{s}]] | Modeling, SQL behavior hoặc current product semantics liên quan | Đã đọc phạm vi có locator; không suy ngoài phạm vi |' for s in x.source_links)
    parts.append(f'''\n## Reference\n\n{refs}\n\n## Source coverage\n\n| Source slice | Nội dung sử dụng | Trạng thái |\n|---|---|---|\n{coverage}\n\n## Key takeaways\n\n- Join correctness phải được chứng minh bằng grain, multiplicity, unmatched ledger và independent oracle.\n- Metric–dimension compatibility là rule ba trạng thái có lý do, không phải danh sách field tùy ý.\n- Parse/validate/compile không thay reconciliation với business contract.\n- Generated SQL phải được đọc theo population, path, aggregation và time/filter semantics.\n- Chưa chạy protocol thì note là tài liệu học thuật có truy nguồn, không phải chứng nhận production.\n''')
    return ''.join(parts)

def folder(x): return BASE/x.directory
def field(text,name):
    match=re.search(rf'(?m)^\*\*{re.escape(name)}\.\*\*\s*(.+)$',text)
    if not match: raise ValueError(name)
    return match.group(1).strip()
def section(text,heading):
    match=re.search(rf'(?ms)^## {re.escape(heading)}\n\n(.*?)(?=^## |\Z)',text)
    if not match: raise ValueError(heading)
    return match.group(1).strip()
def contract(x):
    note=(folder(x)/'note.md').read_text(); after=(folder(x)/'after-note.md').read_text()
    if '**Outcome.**' in note: return tuple(field(note,k) for k in ('Outcome','Đánh giá','Lab','Pitfalls','Self-study (2,4 giờ)','Done when'))
    return (field(section(note,'Mục tiêu bài học'),'Năng lực cần chứng minh'),field(section(after,'Tiêu chí hoàn thành'),'Cách đánh giá'),field(section(after,'Thực hành'),'Nhiệm vụ'),field(section(after,'Bài làm sau buổi học'),'Lỗi cần chủ động loại trừ'),field(section(after,'Bài làm sau buổi học'),'Nhiệm vụ'),field(section(note,'Mục tiêu bài học'),'Điều kiện hoàn thành'))
def curriculum(x,knowledge):
    outcome,assessment,lab,pitfalls,homework,done=contract(x)
    header=f'# Phase 5: Modeling, Semantics and Analytical Product\n# Module 12: Semantic Layer and Metrics Engineering\n# Lesson {x.number}: {x.title}'
    body=re.sub(r'^---\n.*?\n---\n','',knowledge,flags=re.S); body=re.sub(r'^# .+\n+','',body,count=1)
    note=f'{header}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {outcome}\n\n**Điều kiện hoàn thành.** {done}\n\n{body}'
    safety='Chỉ chạy join fixtures, MetricFlow validation/compile và execution plans trên dataset/môi trường thử nghiệm có version. Không chạy query tốn kém hoặc thay semantic configuration production. Redact credentials; lưu config/tool version, seed, commands, raw output và diff.'
    questions='\n'.join(f'{i}. {q}' for i,q in enumerate(('Phát biểu grains, identities và expected cardinalities.','Nêu phản ví dụ cho fanout, lost population hoặc ambiguous path.','Phân biệt parse, validate, compile và business reconciliation.','Đề xuất independent oracle cùng valid/invalid controls.'),1))
    after=f'{header}\n\n## Thực hành\n\n**Nhiệm vụ.** {lab}\n\n{safety}\n\n## Kiểm tra cuối bài\n\n{questions}\n\n## Tiêu chí hoàn thành\n\n**Cách đánh giá.** {assessment}\n\n**Điều kiện đạt.** {done}\n\n## Bài làm sau buổi học\n\n**Nhiệm vụ.** {homework}\n\n**Lỗi cần chủ động loại trừ.** {pitfalls}\n\n## Reference\n\n- Knowledge note: `{(PACK/x.filename).relative_to(ROOT)}`\n- Nội dung học thuật: `note.md` cùng thư mục.\n'
    return note,after

QUERIES={
171:['Chasm trap nhân hai fact tables ra sao?','Ba cách sửa fact-to-fact join là gì?','Ambiguous join path phải bị chặn thế nào?'],
172:['Fanout proof bốn bước gồm gì?','Independent oracle khác generated SQL thế nào?','Khi nào metric certificate phải invalidated?'],
173:['Compatibility matrix có ba trạng thái nào?','Dimension reachable nhưng incompatible vì sao?','Làm sao kiểm engine không chặn nhầm query hợp lệ?'],
174:['Current MetricFlow semantic model khác legacy spec thế nào?','Parse validate compile xác nhận gì?','Entity dimension metric trace về contract ra sao?'],
175:['Bốn điểm soi generated SQL là gì?','Dataflow plan khác warehouse execution plan thế nào?','Injected semantic defect được tìm bằng SQL ra sao?'],
}
def update_manifest(check=False):
    path=ROOT/'Docs/Second-Brain/second-brain-manifest.json'; data=json.loads(path.read_text()); ids={x.note_id for x in LESSONS}
    data['note_registry']=[n for n in data['note_registry'] if n.get('note_id') not in ids]; data['retrieval_test_set']=[q for q in data['retrieval_test_set'] if q.get('expected_note_id') not in ids]
    for x in LESSONS:
        data['note_registry'].append({'note_id':x.note_id,'path':f'2_Wiki/Database-Systems/{x.title}.md','status':'review','source_ids':list(x.sources),'last_verified':'2026-10-01'})
        data['retrieval_test_set'].extend({'query':q,'expected_note_id':x.note_id} for q in QUERIES[x.number])
    data['version']='1.0.34'; data['updated_at']='2026-10-02T00:20:00+07:00'; data['layers']['1_Nguon']['source_count']=len(data['source_registry']); data['layers']['2_Wiki']['note_count']=len(data['note_registry'])
    expected=json.dumps(data,ensure_ascii=False,indent=2)+'\n'
    if check: return [] if path.read_text()==expected else [str(path.relative_to(ROOT))]
    path.write_text(expected); return []
def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--check',action='store_true'); args=parser.parse_args(); stale=[]
    for x in LESSONS:
        knowledge=normalize_markdown(deep_note(x)); note,after=curriculum(x,knowledge)
        for path,content in ((PACK/x.filename,knowledge),(WIKI/(x.title+'.md'),knowledge),(folder(x)/'note.md',note),(folder(x)/'after-note.md',after)):
            if args.check:
                if not path.exists() or path.read_text()!=content: stale.append(str(path.relative_to(ROOT)))
            else: path.write_text(content)
    stale.extend(update_manifest(args.check))
    if stale: print('STALE\n'+'\n'.join(stale)); return 1
    print(('checked' if args.check else 'written')+f'={len(LESSONS)*4} stale=0'); return 0
if __name__=='__main__': raise SystemExit(main())
